#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K, C;
    cin >> N >> K >> C;

    vector<int> A(N + 1);
    for (int i = 1; i <= N; ++i) {
        cin >> A[i];
    }

    const int NEG = -1000000000;
    int mod = C + 1;

    vector<vector<int>> dp(mod, vector<int>(K + 1, NEG));
    dp[0][0] = 0;

    for (int i = 1; i <= N; ++i) {
        int idx = i % mod;
        int prevIdx = (i - 1) % mod;
        int maxJ = min(K, i / C);

        for (int j = 0; j <= maxJ; ++j) {
            int val = NEG;

            if (dp[prevIdx][j] > NEG / 2) {
                val = dp[prevIdx][j] + A[i];
            }

            if (j >= 1 && i >= C) {
                int oldIdx = (i - C) % mod;
                if (dp[oldIdx][j - 1] > NEG / 2) {
                    val = max(val, dp[oldIdx][j - 1]);
                }
            }

            dp[idx][j] = val;
        }
    }

    cout << dp[N % mod][K] << '\n';
    return 0;
}
